{
  "name": "BuildEstimate Pro",
  "description": "A comprehensive construction planning and cost estimation platform connecting homeowners with professional engineers for accurate project budgeting.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum UserRole {
  CUSTOMER = 'CUSTOMER',
  ENGINEER = 'ENGINEER',
  ADMIN = 'ADMIN'
}

export enum ProjectStatus {
  SUBMITTED = 'Submitted',
  UNDER_REVIEW = 'Under Review',
  ESTIMATED = 'Estimated'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  isApproved?: boolean; // For Engineers
  experience?: number; // For Engineers
  profileImage?: string;
}

export interface ConstructionDetails {
  plotArea: number; // in sq ft
  rooms: number;
  floors: number;
  parking: boolean;
  notes?: string;
}

export interface Estimate {
  engineerId: string;
  engineerName: string;
  materialCost: number;
  laborCost: number;
  submittedAt: string;
}

export interface Project {
  id: string;
  customerId: string;
  customerName: string;
  details: ConstructionDetails;
  status: ProjectStatus;
  createdAt: string;
  aiEstimate?: {
    material: number;
    labor: number;
    explanation: string;
  };
  estimates: Estimate[];
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ConstructionDetails } from "../types";

export const getAiEstimate = async (details: ConstructionDetails) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `Provide a rough preliminary construction cost estimate for a house with the following specs:
    - Plot Area: ${details.plotArea} sq ft
    - Rooms: ${details.rooms}
    - Floors: ${details.floors}
    - Parking: ${details.parking ? "Required" : "Not Required"}
    - Additional Notes: ${details.notes || "None"}

    Calculate a realistic material cost and labor cost based on current global averages. Provide a brief 2-sentence explanation of the calculation logic.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            material: { type: Type.NUMBER, description: "Estimated material cost in USD" },
            labor: { type: Type.NUMBER, description: "Estimated labor cost in USD" },
            explanation: { type: Type.STRING, description: "Brief explanation" },
          },
          required: ["material", "labor", "explanation"],
        },
      },
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      material: details.plotArea * 150,
      labor: details.plotArea * 80,
      explanation: "Fallback estimate based on standard industry averages."
    };
  }
};

import React, { useState, useEffect } from 'react';
import { User, UserRole, Project, AuthState } from './types';
import Navbar from './components/Navbar';
import Home from './views/Home';
import AuthView from './views/Auth';
import CustomerDashboard from './views/CustomerDashboard';
import EngineerDashboard from './views/EngineerDashboard';
import AdminDashboard from './views/AdminDashboard';
import { initialProjects, initialUsers } from './constants';

const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>(() => {
    const saved = localStorage.getItem('auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('users');
    return saved ? JSON.parse(saved) : initialUsers;
  });

  const [projects, setProjects] = useState<Project[]>(() => {
    const saved = localStorage.getItem('projects');
    return saved ? JSON.parse(saved) : initialProjects;
  });

  const [currentView, setCurrentView] = useState<'home' | 'auth' | 'dashboard'>('home');

  useEffect(() => {
    localStorage.setItem('auth', JSON.stringify(authState));
    localStorage.setItem('users', JSON.stringify(users));
    localStorage.setItem('projects', JSON.stringify(projects));
  }, [authState, users, projects]);

  const handleLogin = (user: User) => {
    setAuthState({ user, isAuthenticated: true });
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setAuthState({ user: null, isAuthenticated: false });
    setCurrentView('home');
  };

  const updateProject = (updatedProject: Project) => {
    setProjects(prev => prev.map(p => p.id === updatedProject.id ? updatedProject : p));
  };

  const addProject = (newProject: Project) => {
    setProjects(prev => [newProject, ...prev]);
  };

  const updateUsers = (updatedUsers: User[]) => {
    setUsers(updatedUsers);
  };

  const renderContent = () => {
    if (currentView === 'home') return <Home onGetStarted={() => setCurrentView('auth')} />;
    if (currentView === 'auth') return <AuthView onLogin={handleLogin} users={users} setUsers={setUsers} />;

    if (currentView === 'dashboard' && authState.user) {
      switch (authState.user.role) {
        case UserRole.CUSTOMER:
          return (
            <CustomerDashboard 
              user={authState.user} 
              projects={projects.filter(p => p.customerId === authState.user?.id)} 
              onAddProject={addProject}
            />
          );
        case UserRole.ENGINEER:
          return (
            <EngineerDashboard 
              user={authState.user} 
              projects={projects} 
              onUpdateProject={updateProject}
            />
          );
        case UserRole.ADMIN:
          return (
            <AdminDashboard 
              users={users} 
              setUsers={updateUsers} 
              projects={projects} 
            />
          );
      }
    }
    return <Home onGetStarted={() => setCurrentView('auth')} />;
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar 
        user={authState.user} 
        onLogout={handleLogout} 
        onNavHome={() => setCurrentView('home')}
        onNavDashboard={() => setCurrentView('dashboard')}
        onNavLogin={() => setCurrentView('auth')}
      />
      <main className="flex-grow">
        {renderContent()}
      </main>
      <footer className="bg-slate-900 text-white py-8 px-4 text-center">
        <p className="text-slate-400">© 2024 BuildEstimate Pro. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default App;

