import React, { useState } from 'react';
import { User, Project, ProjectStatus, ConstructionDetails } from '../types';
import { getAiEstimate } from '../services/geminiService';

interface CustomerDashboardProps {
  user: User;
  projects: Project[];
  onAddProject: (p: Project) => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, projects, onAddProject }) => {
