import { GoogleGenAI, Type } from "@google/genai";
import { ConstructionDetails } from "../types";

export const getAiEstimate = async (details: ConstructionDetails) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `Provide a rough preliminary construction cost estimate for a house in India with the following specs:
    - Plot Area: ${details.plotArea} sq ft
    - Rooms: ${details.rooms}
    - Floors: ${details.floors}
    - Parking: ${details.parking ? "Required" : "Not Required"}
    - Additional Notes: ${details.notes || "None"}

    Calculate a realistic material cost and labor cost in Indian Rupees (INR) based on current Indian market averages. Provide a brief 2-sentence explanation of the calculation logic.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            material: { type: Type.NUMBER, description: "Estimated material cost in INR" },
            labor: { type: Type.NUMBER, description: "Estimated labor cost in INR" },
            explanation: { type: Type.STRING, description: "Brief explanation" },
          },
          required: ["material", "labor", "explanation"],
        },
      },
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Gemini API Error:", error);
    // Fallback based on ~₹2000 per sq ft for India
    return {
      material: details.plotArea * 1200,
      labor: details.plotArea * 800,
      explanation: "Fallback estimate based on standard Indian construction industry averages (approx ₹2000/sqft)."
    };
  }
};

