import React, { useState } from 'react';
import { User, Project, ProjectStatus, ConstructionDetails } from '../types';
import { getAiEstimate } from '../services/geminiService';

interface CustomerDashboardProps {
  user: User;
  projects: Project[];
  onAddProject: (p: Project) => void;
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);
};

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, projects, onAddProject }) => {
  const [showWizard, setShowWizard] = useState(false);
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [details, setDetails] = useState<ConstructionDetails>({
    plotArea: 1000,
    rooms: 2,
    floors: 1,
    parking: false,
    notes: ''
  });

  const inputClasses = "w-full p-4 rounded-xl border border-slate-300 bg-slate-100 text-slate-950 focus:bg-white focus:ring-2 focus:ring-orange-100 focus:border-orange-500 outline-none transition-all font-medium";

  const handleNext = () => setStep(prev => prev + 1);
  const handleBack = () => setStep(prev => prev - 1);

  const handleSubmit = async () => {
    setLoading(true);
    // Get AI Estimate immediately
    const aiEst = await getAiEstimate(details);

    const newProject: Project = {
      id: 'p' + Math.random().toString(36).substr(2, 5),
      customerId: user.id,
      customerName: user.name,
      status: ProjectStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      details,
      aiEstimate: aiEst,
      estimates: []
    };

    onAddProject(newProject);
    setLoading(false);
    setShowWizard(false);
    setStep(1);
  };

  return (
    <div className="max-w-6xl mx-auto p-6 md:p-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-10">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-900">Your Projects</h2>
          <p className="text-slate-500">Manage your house construction planning and estimates.</p>
        </div>
        <button 
          onClick={() => setShowWizard(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-orange-100 transition-all"
        >
          <i className="fas fa-plus"></i>
          New Project
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {projects.length === 0 ? (
          <div className="col-span-full bg-white border-2 border-dashed border-slate-200 rounded-3xl p-20 text-center">
            <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-300 text-3xl">
              <i className="fas fa-folder-open"></i>
            </div>
            <h3 className="text-xl font-bold text-slate-700">No projects yet</h3>
            <p className="text-slate-500 mt-2 mb-8">Start by creating your first construction plan.</p>
            <button 
              onClick={() => setShowWizard(true)}
              className="text-orange-500 font-bold hover:underline"
            >
              Start Planning Now &rarr;
            </button>
          </div>
        ) : (
          projects.map(p => (
            <div key={p.id} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${
                    p.status === ProjectStatus.ESTIMATED ? 'bg-green-100 text-green-700' : 
                    p.status === ProjectStatus.UNDER_REVIEW ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                  }`}>
                    {p.status}
                  </span>
                  <p className="text-xs text-slate-400 mt-2">ID: {p.id}</p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-slate-800">{p.details.plotArea} sq ft</p>
                  <p className="text-xs text-slate-500">{p.details.rooms} Rooms, {p.details.floors} Floor(s)</p>
                </div>
              </div>

              {p.aiEstimate && p.estimates.length === 0 && (
                <div className="mb-6 p-4 bg-orange-50 rounded-xl border border-orange-100">
                  <div className="flex items-center gap-2 text-orange-700 text-xs font-bold mb-2 uppercase">
                    <i className="fas fa-robot"></i> AI Initial Estimate (INR)
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-xs text-slate-500">Materials</p>
                      <p className="font-bold text-slate-900">{formatCurrency(p.aiEstimate.material)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-slate-500">Labor</p>
                      <p className="font-bold text-slate-900">{formatCurrency(p.aiEstimate.labor)}</p>
                    </div>
                  </div>
                </div>
              )}

              {p.estimates.length > 0 ? (
                <div className="space-y-4">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Professional Estimate</h4>
                  {p.estimates.map((est, i) => (
                    <div key={i} className="p-4 bg-slate-50 rounded-xl">
                      <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-bold text-slate-800">{est.engineerName}</span>
                        <span className="text-[10px] text-slate-400">{new Date(est.submittedAt).toLocaleDateString()}</span>
                      </div>
                      <div className="grid grid-cols-1 gap-2 text-sm">
                        <div className="flex justify-between border-b border-slate-100 pb-1">
                          <span className="text-slate-500">Materials:</span>
                          <span className="font-semibold">{formatCurrency(est.materialCost)}</span>
                        </div>
                        <div className="flex justify-between border-b border-slate-100 pb-1">
                          <span className="text-slate-500">Labor:</span>
                          <span className="font-semibold">{formatCurrency(est.laborCost)}</span>
                        </div>
                      </div>
                      <div className="mt-3 pt-2 flex justify-between">
                        <span className="text-sm font-bold text-slate-900">Total:</span>
                        <span className="text-sm font-bold text-orange-600">{formatCurrency(est.materialCost + est.laborCost)}</span>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="mt-4 flex items-center gap-2 text-blue-500 text-sm italic">
                  <i className="fas fa-spinner fa-spin"></i>
                  Waiting for engineer review...
                </div>
              )}
            </div>
          ))
        )}
      </div>

      {/* Project Wizard Overlay */}
      {showWizard && (
        <div className="fixed inset-0 z-[60] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-3xl overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-300 border border-slate-200">
            <div className="bg-slate-900 text-white p-6 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold">New Construction Plan</h3>
                <p className="text-slate-400 text-sm">Step {step} of 3</p>
              </div>
              <button onClick={() => {setShowWizard(false); setStep(1);}} className="text-slate-400 hover:text-white transition-colors">
                <i className="fas fa-times text-xl"></i>
              </button>
            </div>

            <div className="p-8">
              {step === 1 && (
                <div className="space-y-6">
                  <h4 className="text-xl font-bold text-slate-900">Plot Details</h4>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Plot/House Area (sq ft)</label>
                    <input 
                      type="number" 
                      className={inputClasses}
                      value={details.plotArea}
                      onChange={e => setDetails({...details, plotArea: Number(e.target.value)})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Number of Floors</label>
                    <div className="flex gap-4">
                      {[1, 2, 3, 4].map(num => (
                        <button 
                          key={num}
                          onClick={() => setDetails({...details, floors: num})}
                          className={`flex-1 py-3 rounded-xl border font-bold transition-all ${details.floors === num ? 'bg-orange-500 border-orange-500 text-white shadow-lg shadow-orange-100' : 'bg-slate-100 border-slate-300 text-slate-600 hover:border-orange-200'}`}
                        >
                          {num}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              {step === 2 && (
                <div className="space-y-6">
                  <h4 className="text-xl font-bold text-slate-900">Room Configuration</h4>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Number of Rooms</label>
                    <input 
                      type="number" 
                      className={inputClasses}
                      value={details.rooms}
                      onChange={e => setDetails({...details, rooms: Number(e.target.value)})}
                    />
                  </div>
                  <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-200">
                    <div>
                      <p className="font-bold text-slate-900">Parking Space</p>
                      <p className="text-sm text-slate-500">Include dedicated garage or parking lot</p>
                    </div>
                    <button 
                      onClick={() => setDetails({...details, parking: !details.parking})}
                      className={`w-14 h-8 rounded-full transition-colors relative ${details.parking ? 'bg-green-500' : 'bg-slate-300'}`}
                    >
                      <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${details.parking ? 'left-7' : 'left-1'}`}></div>
                    </button>
                  </div>
                </div>
              )}

              {step === 3 && (
                <div className="space-y-6">
                  <h4 className="text-xl font-bold text-slate-900">Review & Notes</h4>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Special Instructions (Optional)</label>
                    <textarea 
                      className={inputClasses + " h-32 resize-none"}
                      placeholder="e.g., Rooftop garden, eco-friendly materials..."
                      value={details.notes}
                      onChange={e => setDetails({...details, notes: e.target.value})}
                    ></textarea>
                  </div>
                  <div className="bg-slate-100 p-6 rounded-2xl border border-slate-300 space-y-2 shadow-inner">
                    <p className="flex justify-between text-sm"><span className="text-slate-600">Area:</span> <span className="font-bold text-slate-900">{details.plotArea} sq ft</span></p>
                    <p className="flex justify-between text-sm"><span className="text-slate-600">Config:</span> <span className="font-bold text-slate-900">{details.rooms} Rooms, {details.floors} Floors</span></p>
                    <p className="flex justify-between text-sm"><span className="text-slate-600">Parking:</span> <span className="font-bold text-slate-900">{details.parking ? 'Yes' : 'No'}</span></p>
                  </div>
                </div>
              )}
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 flex gap-4">
              {step > 1 && (
                <button 
                  onClick={handleBack}
                  className="px-6 py-3 rounded-xl font-bold text-slate-600 hover:bg-slate-200 transition-all border border-slate-200"
                >
                  Back
                </button>
              )}
              <button 
                onClick={step === 3 ? handleSubmit : handleNext}
                disabled={loading}
                className="flex-1 bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white py-3 rounded-xl font-bold shadow-lg shadow-orange-100 transition-all flex items-center justify-center gap-2"
              >
                {loading ? (
                  <>
                    <i className="fas fa-spinner fa-spin"></i>
                    Generating AI Estimate...
                  </>
                ) : (
                  step === 3 ? 'Submit Project' : 'Continue'
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerDashboard;

import React, { useState } from 'react';
import { User, Project, ProjectStatus, Estimate } from '../types';

interface EngineerDashboardProps {
  user: User;
  projects: Project[];
  onUpdateProject: (p: Project) => void;
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);
};

const EngineerDashboard: React.FC<EngineerDashboardProps> = ({ user, projects, onUpdateProject }) => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [materialCost, setMaterialCost] = useState<number>(0);
  const [laborCost, setLaborCost] = useState<number>(0);

  const inputClasses = "w-full p-4 rounded-xl border border-slate-300 bg-slate-100 text-slate-950 focus:bg-white focus:ring-2 focus:ring-orange-100 outline-none transition-all font-medium";

  if (!user.isApproved) {
    return (
      <div className="max-w-4xl mx-auto my-20 text-center p-12 bg-white rounded-3xl shadow-xl border border-slate-100">
        <div className="bg-amber-100 text-amber-600 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-3xl">
          <i className="fas fa-user-clock"></i>
        </div>
        <h2 className="text-3xl font-extrabold text-slate-900">Registration Pending</h2>
        <p className="text-slate-500 mt-4 max-w-md mx-auto leading-relaxed">
          Welcome, {user.name}! Your professional profile is currently under review by our admin team. Once approved, you'll be able to see and estimate construction projects.
        </p>
        <div className="mt-8 flex justify-center gap-4">
          <div className="p-4 bg-slate-50 rounded-2xl flex flex-col items-center">
            <span className="text-sm text-slate-400">Experience</span>
            <span className="font-bold text-slate-800">{user.experience} Years</span>
          </div>
          <div className="p-4 bg-slate-50 rounded-2xl flex flex-col items-center">
            <span className="text-sm text-slate-400">Status</span>
            <span className="font-bold text-amber-500">Reviewing</span>
          </div>
        </div>
      </div>
    );
  }

  const handleEstimateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProject) return;

    const newEstimate: Estimate = {
      engineerId: user.id,
      engineerName: user.name,
      materialCost,
      laborCost,
      submittedAt: new Date().toISOString()
    };

    const updatedProject: Project = {
      ...selectedProject,
      status: ProjectStatus.ESTIMATED,
      estimates: [...selectedProject.estimates.filter(e => e.engineerId !== user.id), newEstimate]
