                {user.name.charAt(0)}
              </div>
              <div>
                <h2 className="text-xl font-bold">{user.name}</h2>
                <p className="text-slate-400 text-sm">Professional Engineer</p>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4 mt-6">
              <div className="bg-white/10 p-3 rounded-xl">
                <p className="text-xs text-slate-400">Exp</p>
                <p className="font-bold">{user.experience} Years</p>
              </div>
              <div className="bg-white/10 p-3 rounded-xl">
                <p className="text-xs text-slate-400">Status</p>
                <p className="font-bold text-green-400">Verified</p>
              </div>
            </div>
          </div>
          <div className="p-6">
            <h3 className="font-bold text-slate-900 mb-4">Quick Stats</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Estimates Sent</span>
                <span className="font-bold">14</span>
              </div>
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Conversion Rate</span>
                <span className="font-bold">64%</span>
              </div>
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Response Time</span>
                <span className="font-bold">~4h</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="flex-grow">
        <div className="mb-8">
          <h2 className="text-3xl font-extrabold text-slate-900">Available Projects</h2>
          <p className="text-slate-500">Review project requirements and provide your expert estimation in ₹ (INR).</p>
        </div>

        <div className="space-y-4">
          {projects.map(p => {
            const myEstimate = p.estimates.find(e => e.engineerId === user.id);
            return (
              <div 
                key={p.id} 
                className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${
                  selectedProject?.id === p.id ? 'border-orange-500 ring-4 ring-orange-50' : 'border-slate-100 hover:border-slate-200'
