                      <div className="text-right">
                        <p className="text-xs text-slate-400">Your Estimate</p>
                        <p className="font-bold text-green-600">{formatCurrency(myEstimate.materialCost + myEstimate.laborCost)}</p>
                        <button 
                          onClick={() => {
                            setSelectedProject(p);
                            setMaterialCost(myEstimate.materialCost);
                            setLaborCost(myEstimate.laborCost);
                          }}
                          className="text-orange-500 text-xs font-bold hover:underline"
                        >
                          Update Estimate
                        </button>
                      </div>
                    ) : (
                      <button 
                        onClick={() => {
                          setSelectedProject(p);
                          setMaterialCost(p.aiEstimate?.material || 0);
                          setLaborCost(p.aiEstimate?.labor || 0);
                        }}
                        className="bg-slate-900 text-white px-6 py-2 rounded-xl text-sm font-bold hover:bg-slate-800 transition-colors"
                      >
                        Submit Estimate
                      </button>
                    )}
                  </div>
