                      <div>
                        <label className="block text-sm font-semibold text-slate-700 mb-2">Estimated Material Cost (₹)</label>
                        <input 
                          type="number" 
                          required
                          className={inputClasses}
                          value={materialCost}
                          onChange={e => setMaterialCost(Number(e.target.value))}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-semibold text-slate-700 mb-2">Estimated Labor Cost (₹)</label>
                        <input 
                          type="number" 
                          required
                          className={inputClasses}
                          value={laborCost}
                          onChange={e => setLaborCost(Number(e.target.value))}
                        />
                      </div>
                    </div>
                    <div className="mt-6 flex gap-4">
                      <button 
                        type="submit"
                        className="flex-1 bg-orange-500 text-white py-4 rounded-xl font-bold shadow-lg shadow-orange-100 hover:bg-orange-600 transition-all"
                      >
                        {myEstimate ? 'Update My Quote' : 'Send Quote to Customer'}
                      </button>
                      <button 
                        type="button"
                        onClick={() => setSelectedProject(null)}
                        className="px-6 py-4 rounded-xl font-bold text-slate-500 hover:bg-slate-100 border border-slate-200"
                      >
                        Cancel
                      </button>
                    </div>
                  </form>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

