import React, { useState, useEffect } from 'react';

interface LocationData {
  latitude: number | null;
  longitude: number | null;
  address?: string;
}

const LocationWidget: React.FC = () => {
  const [location, setLocation] = useState<LocationData>({ latitude: null, longitude: null });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchLocation = () => {
    setLoading(true);
    setError(null);

    if (!navigator.geolocation) {
      setError("Geolocation is not supported by your browser");
      setLoading(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        setLocation({ latitude, longitude });

        // Reverse geocoding attempt (using free Nominatim API for demo)
        try {
          const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await res.json();
          if (data && data.display_name) {
            setLocation(prev => ({ ...prev, address: data.display_name }));
          }
        } catch (e) {
          console.error("Geocoding failed", e);
        }
        setLoading(false);
      },
      (err) => {
        setError(err.message);
        setLoading(false);
      },
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
    );
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-100 p-6 overflow-hidden">
      <div className="flex items-center justify-between mb-4">
        <h3 className="font-bold text-slate-900 flex items-center gap-2">
          <i className="fas fa-map-marker-alt text-orange-500"></i>
          Project Location
        </h3>
        <button 
          onClick={fetchLocation}
          disabled={loading}
          className="text-xs font-bold text-orange-500 hover:text-orange-600 transition-colors uppercase tracking-wider disabled:opacity-50"
        >
          {loading ? 'Locating...' : 'Update'}
        </button>
      </div>

      <div className="space-y-3">
        {location.latitude ? (
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="p-3 bg-slate-50 rounded-xl border border-slate-200">
              <p className="text-xs text-slate-500 mb-1 font-semibold uppercase tracking-tighter">Current Address</p>
              <p className="text-sm text-slate-800 font-medium line-clamp-2">
                {location.address || 'Address pinpointed'}
              </p>
            </div>
            <div className="mt-3 flex gap-2">
              <div className="flex-1 p-2 bg-slate-50 rounded-lg border border-slate-100 text-center">
                <p className="text-[10px] text-slate-400">Lat</p>
                <p className="text-xs font-bold text-slate-700">{location.latitude.toFixed(4)}</p>
              </div>
              <div className="flex-1 p-2 bg-slate-50 rounded-lg border border-slate-100 text-center">
                <p className="text-[10px] text-slate-400">Long</p>
                <p className="text-xs font-bold text-slate-700">{location.longitude.toFixed(4)}</p>
              </div>
            </div>
          </div>
        ) : (
          <div className="py-6 text-center border-2 border-dashed border-slate-100 rounded-2xl">
            <div className="text-slate-200 text-2xl mb-2">
              <i className="fas fa-location-arrow"></i>
            </div>
            <p className="text-xs text-slate-400 font-medium px-4">
              Set location for more accurate material & labor costs in your area.
            </p>
            <button 
              onClick={fetchLocation}
              className="mt-3 text-xs bg-slate-900 text-white px-4 py-2 rounded-lg font-bold hover:bg-slate-800 transition-all"
            >
              Get Location
            </button>
          </div>
        )}

        {error && (
          <div className="p-3 bg-red-50 border border-red-100 rounded-xl flex items-start gap-2">
            <i className="fas fa-exclamation-circle text-red-400 mt-0.5"></i>
            <p className="text-[10px] text-red-600 leading-tight font-medium">
              Error: {error}. Please enable location permissions.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

