import { GoogleGenAI, Type } from "@google/genai";
import { ConstructionDetails } from "../types";

export const getAiEstimate = async (details: ConstructionDetails) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const floorBreakdown = details.floorConfigs.map(f => 
    `Floor ${f.floorNumber}: ${f.rooms} Rooms, ${f.bathrooms} Bathrooms, Kitchen: ${f.kitchenType}`
  ).join('\n');

  const prompt = `Provide a detailed preliminary construction cost estimate for a house in India with the following specs:
    - Plot Area: ${details.plotArea} sq ft
    - Total Floors: ${details.floors}
    - Floor Breakdown:
${floorBreakdown}
    - Parking: ${details.parking ? "Required" : "Not Required"}
    - Additional Notes: ${details.notes || "None"}

    Calculate a realistic material cost and labor cost in Indian Rupees (INR) based on current Indian market averages. Note that kitchens with chimneys add significant cost to plumbing and ventilation. Provide a brief 2-sentence explanation of the calculation logic.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            material: { type: Type.NUMBER, description: "Estimated material cost in INR" },
            labor: { type: Type.NUMBER, description: "Estimated labor cost in INR" },
            explanation: { type: Type.STRING, description: "Brief explanation" },
          },
          required: ["material", "labor", "explanation"],
        },
      },
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Gemini API Error:", error);
    // Dynamic fallback based on complexity
    const roomsCount = details.floorConfigs.reduce((sum, f) => sum + f.rooms, 0);
    const materialEst = (details.plotArea * 1300) + (roomsCount * 50000);
    const laborEst = (details.plotArea * 900) + (roomsCount * 30000);

    return {
      material: materialEst,
      labor: laborEst,
      explanation: "Fallback estimate calculated based on total floor area and complexity (rooms/bathrooms/floors)."
    };
  }
};

