                            >
                              Without Chimney
                            </button>
                            <button 
                              onClick={() => updateFloorConfig(f.floorNumber, 'kitchenType', 'With Chimney')}
                              className={`py-2 rounded-lg text-xs font-bold transition-all ${f.kitchenType === 'With Chimney' ? 'bg-orange-500 text-white shadow-lg shadow-orange-100' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                              With Chimney
                            </button>
