                    >
                      <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${details.parking ? 'left-7' : 'left-1'}`}></div>
                    </button>
                  </div>
                </div>
              )}

              {step === 3 && (
                <div className="space-y-6">
                  <h4 className="text-xl font-bold text-slate-900">Review & Notes</h4>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Special Instructions (Optional)</label>
                    <textarea 
                      className={inputClasses + " h-32 resize-none"}
                      placeholder="e.g., Rooftop garden, specific materials, wood finishes..."
                      value={details.notes}
                      onChange={e => setDetails({...details, notes: e.target.value})}
                    ></textarea>
                  </div>
                  <div className="bg-slate-100 p-6 rounded-2xl border border-slate-300 space-y-4 shadow-inner">
                    <div className="flex justify-between items-center pb-2 border-b border-slate-200">
                      <span className="text-slate-600 font-medium">Plot Area:</span> 
                      <span className="font-bold text-slate-900">{details.plotArea} sq ft</span>
                    </div>
                    <div className="flex justify-between items-center pb-2 border-b border-slate-200">
                      <span className="text-slate-600 font-medium">Structure:</span> 
                      <span className="font-bold text-slate-900">{details.floors} Floors</span>
                    </div>
                    <div className="flex justify-between items-center pb-2 border-b border-slate-200">
                      <span className="text-slate-600 font-medium">Overall Config:</span> 
                      <span className="font-bold text-orange-600">
                        {details.floorConfigs.reduce((s, f) => s + f.rooms, 0)}R / 
                        {details.floorConfigs.reduce((s, f) => s + f.bathrooms, 0)}B
                      </span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 flex gap-4">
              {step > 1 && (
                <button 
                  onClick={handleBack}
                  className="px-6 py-3 rounded-xl font-bold text-slate-600 hover:bg-slate-200 transition-all border border-slate-200"
                >
                  Back
                </button>
              )}
              <button 
                onClick={step === 3 ? handleSubmit : handleNext}
                disabled={loading}
                className="flex-1 bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white py-3 rounded-xl font-bold shadow-lg shadow-orange-100 transition-all flex items-center justify-center gap-2"
              >
                {loading ? (
                  <>
                    <i className="fas fa-spinner fa-spin"></i>
                    Generating AI Estimate...
                  </>
                ) : (
                  step === 3 ? 'Submit Project' : 'Continue'
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

