              <h2 className="text-2xl font-black uppercase tracking-tight italic">{user.name}</h2>
              <p className="text-construction-yellow text-[10px] font-black uppercase tracking-widest mt-1 border-t border-white/20 pt-1">Authorized Site Owner</p>
            </div>
