export const supabaseService = {
  // Projects (Orders)
  async getProjects(): Promise<Project[]> {
    const { data, error } = await supabase
      .from('projects')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Error fetching projects:', error);
      return [];
    }

    // Map snake_case database fields to camelCase Project interface
    return (data || []).map(p => ({
      ...p,
      mobile_number: p.mobile_number, // Keeps mobile_number for now to avoid breaking view
      createdAt: p.created_at,
      customerName: p.customer_name,
      customerId: p.customer_id
    }));
  },

  async upsertProject(project: Project) {
    const dbProject = {
      id: project.id,
      customer_id: project.customerId,
      customer_name: project.customerName,
      first_name: project.firstName,
      last_name: project.lastName,
      email: project.email,
      mobile_number: project.mobile_number,
      details: project.details,
      status: project.status,
      estimates: project.estimates,
      messages: project.messages,
      created_at: project.createdAt
    };

    const { error } = await supabase
      .from('projects')
      .upsert(dbProject);

    if (error) console.error('Error saving project:', error);
  },

  // Users
  async getUsers(): Promise<User[]> {
    const { data, error } = await supabase
      .from('users')
      .select('*');

    if (error) {
      console.error('Error fetching users:', error);
      return [];
    }

    return (data || []).map(u => ({
      ...u,
      isApproved: u.is_approved,
      firstName: u.first_name,
      lastName: u.last_name
    }));
  },

  async upsertUser(user: User) {
    const dbUser = {
      id: user.id,
      name: user.name,
      first_name: user.firstName,
      last_name: user.lastName,
      email: user.email,
      password: user.password,
      role: user.role,
      is_approved: user.isApproved,
      experience: user.experience,
      phone: user.phone,
      address: user.address,
      profile_image: user.profileImage
    };

    const { error } = await supabase
      .from('users')
      .upsert(dbUser);

    if (error) console.error('Error saving user:', error);
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { ConstructionDetails, AiEstimateOption } from "../types";

export const getAiEstimateOptions = async (details: ConstructionDetails): Promise<AiEstimateOption[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const floorBreakdown = details.floorConfigs.map(f => 
    `Floor ${f.floorNumber}: ${f.rooms} Rooms, ${f.bathrooms} Bathrooms, Kitchen: ${f.kitchenType}`
  ).join('\n');

  const prompt = `Provide 6 distinct construction cost estimate tiers for a house in India with the following specs:
    - Plot Area: ${details.plotArea} sq ft
    - Total Floors: ${details.floors}
    - Floor Breakdown:
${floorBreakdown}
    - Parking: ${details.parking ? "Required" : "Not Required"}
    - Additional Notes: ${details.notes || "None"}

    The 6 tiers should be:
    1. Economy, 2. Budget-Friendly, 3. Standard, 4. Premium, 5. Luxury, 6. Ultra-Luxury.
    Calculate realistic material and labor costs in INR. Explain briefly what defines each tier.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              label: { type: Type.STRING },
              material: { type: Type.NUMBER },
              labor: { type: Type.NUMBER },
              explanation: { type: Type.STRING },
            },
            required: ["label", "material", "labor", "explanation"],
          }
        },
      },
    });

    return JSON.parse(response.text?.trim() || "[]");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return [];
  }
};

export const generateHouseLayout = async (details: ConstructionDetails): Promise<string | null> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const floor1 = details.floorConfigs[0];
  const prompt = `Professional 2D architectural floor plan for a ${details.plotArea} sq ft site. 
    Level 1 contains ${floor1.rooms} rooms, ${floor1.bathrooms} bathrooms, and a kitchen (${floor1.kitchenType}). 
    ${details.parking ? "Include a dedicated parking area/garage." : "No parking."}
    Style: Technical drawing, white background, black lines, blue accent colors for water areas, labels for rooms.
    Top-down blueprint perspective. Realistic architectural standards.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("Gemini Image Generation Error:", error);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { User, Project, ProjectStatus, ConstructionDetails, FloorConfig, Estimate, ChatMessage } from '../types';
import LocationWidget from '../components/LocationWidget';
import ChatRoom from '../components/ChatRoom';
