                    </button>
                  </div>
                  <div>
                    <label className="block text-xs font-black text-slate-500 uppercase mb-2">Additional Site Intelligence</label>
                    <textarea className={inputClasses + " h-32 resize-none font-medium text-sm"} placeholder="Soil type, elevation details, neighboring wall constraints..." value={details.notes} onChange={e => setDetails({...details, notes: e.target.value})} />
                  </div>
                </div>
              )}

              {step === 4 && (
                <div className="space-y-6">
                  <div className="flex justify-between items-center">
                    <h4 className="text-2xl font-black text-construction-slate uppercase italic">Blueprint Visualization</h4>
                    <button 
                      onClick={handleGenerateLayout}
                      disabled={generatingLayout}
                      className="text-[10px] font-black bg-construction-slate text-construction-yellow px-3 py-1 rounded uppercase tracking-widest hover:scale-105 transition-all disabled:opacity-50"
                    >
                      {generatingLayout ? 'Re-Rendering...' : 'Re-Generate AI Layout'}
                    </button>
                  </div>

                  <div className="relative min-h-[400px] bg-slate-100 rounded-xl border-4 border-construction-slate overflow-hidden flex items-center justify-center shadow-inner">
                    {generatingLayout ? (
                      <div className="text-center">
                        <i className="fas fa-drafting-compass fa-spin text-5xl text-construction-yellow mb-4"></i>
                        <p className="text-xs font-black uppercase tracking-tighter text-slate-500">AI Architect is sketching your site...</p>
                      </div>
                    ) : aiLayoutImage ? (
                      <div className="w-full h-full relative group">
                        <img src={aiLayoutImage} alt="AI Layout" className="w-full h-auto object-contain bg-white" />
                        <div className="absolute top-4 left-4 bg-construction-slate/80 backdrop-blur-md text-white p-3 rounded-lg border-l-4 border-construction-yellow text-[10px] font-bold shadow-xl">
                          <p className="uppercase text-construction-yellow font-black mb-1">AI Generated Floor Plan</p>
                          <p>Area: {details.plotArea} SQ FT</p>
                          <p>Rooms: {details.floorConfigs[0].rooms}</p>
                          <p>Bathrooms: {details.floorConfigs[0].bathrooms}</p>
                          <p>Parking: {details.parking ? 'Allocated' : 'None'}</p>
                        </div>
                        <div className="absolute inset-0 border-[20px] border-transparent pointer-events-none group-hover:border-construction-yellow/10 transition-all"></div>
                      </div>
                    ) : (
                      <div className="text-center p-10">
                        <i className="fas fa-exclamation-triangle text-amber-500 text-3xl mb-4"></i>
                        <p className="text-sm font-black text-slate-400 uppercase">Layout generation failed. Try again.</p>
                      </div>
                    )}
                  </div>
                  <p className="text-[9px] text-slate-400 text-center font-black uppercase tracking-[0.2em] italic">
                    * This is an AI-generated conceptual visualization for reference only.
                  </p>
                </div>
              )}
            </div>

            <div className="p-6 bg-slate-50 flex gap-4 border-t-4 border-construction-yellow">
              {step > 1 && (
                <button onClick={handleBack} className="px-8 py-4 rounded font-black uppercase text-xs text-slate-500 border-2 border-slate-300 hover:bg-slate-100 transition-colors">Previous</button>
              )}
              <button 
                onClick={step === 4 ? handleFinalSubmit : handleNext}
                disabled={loading || generatingLayout}
                className="flex-1 bg-construction-yellow text-construction-slate py-4 rounded font-black uppercase tracking-widest shadow-[4px_4px_0px_0px_rgba(30,41,59,1)] transition-all flex items-center justify-center gap-2 active:shadow-none active:translate-y-1 disabled:opacity-50"
              >
                {loading ? <i className="fas fa-spinner fa-spin"></i> : (step === 4 ? 'Deploy Request' : 'Advance Stage')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

