import { GoogleGenAI, Type } from "@google/genai";
import { ConstructionDetails, AiEstimateOption } from "../types";

export const getAiEstimateOptions = async (details: ConstructionDetails): Promise<AiEstimateOption[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const floorBreakdown = details.floorConfigs.map(f => 
    `Floor ${f.floorNumber}: ${f.rooms} Rooms, ${f.bathrooms} Bathrooms, Kitchen: ${f.kitchenType}`
  ).join('\n');

  const prompt = `Provide 6 distinct construction cost estimate tiers for a house in India with the following specs:
    - Plot Area: ${details.plotArea} sq ft
    - Total Floors: ${details.floors}
    - Floor Breakdown:
${floorBreakdown}
    - Parking: ${details.parking ? "Required" : "Not Required"}
    - Additional Notes: ${details.notes || "None"}

    The 6 tiers should be:
    1. Economy, 2. Budget-Friendly, 3. Standard, 4. Premium, 5. Luxury, 6. Ultra-Luxury.
    Calculate realistic material and labor costs in INR. Explain briefly what defines each tier.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              label: { type: Type.STRING },
              material: { type: Type.NUMBER },
              labor: { type: Type.NUMBER },
              explanation: { type: Type.STRING },
            },
            required: ["label", "material", "labor", "explanation"],
          }
        },
      },
    });

    return JSON.parse(response.text?.trim() || "[]");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return [];
  }
};

export const generateHouseLayout = async (details: ConstructionDetails, style: string = 'Modernist'): Promise<string | null> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const floor1 = details.floorConfigs[0];
  const prompt = `Professional 2D architectural floor plan for a ${details.plotArea} sq ft site. 
    Style: ${style} architectural drawing.
    Level 1 contains ${floor1.rooms} rooms, ${floor1.bathrooms} bathrooms, and a kitchen (${floor1.kitchenType}). 
    ${details.parking ? "Include a dedicated parking area/garage." : "No parking."}
    Visual: White background, black technical lines, industrial blue and yellow accent colors, clear labels for rooms.
    Perspective: Top-down blueprint perspective. Realistic architectural standards for construction.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error(`Gemini Image Generation Error (${style}):`, error);
    return null;
  }
};

export const generateTripleLayouts = async (details: ConstructionDetails): Promise<{url: string, style: string}[]> => {
  const styles = [
    { name: 'Modernist Edge', prompt: 'Modern minimalist luxury with open-plan concepts' },
    { name: 'Classic Heritage', prompt: 'Traditional solid structure with defined separated rooms' },
    { name: 'Eco Minimal', prompt: 'Compact, efficient space optimization with focus on natural flow' }
  ];

  const results = await Promise.all(
    styles.map(async (style) => {
      const url = await generateHouseLayout(details, style.prompt);
      return { url: url || '', style: style.name };
    })
  );

  return results.filter(r => r.url !== '');
};

import React, { useState, useEffect } from 'react';
import { User, Project, ProjectStatus, ConstructionDetails, FloorConfig, Estimate, ChatMessage } from '../types';
import LocationWidget from '../components/LocationWidget';
import ChatRoom from '../components/ChatRoom';
import { generateTripleLayouts } from '../services/geminiService';

interface CustomerDashboardProps {
  user: User;
  projects: Project[];
  onAddProject: (p: Project) => void;
  onUpdateProject: (p: Project) => void;
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);
};

const BUDGET_RANGES = [
  "Below ₹15 Lakhs",
  "₹15 - ₹30 Lakhs",
  "₹30 - ₹50 Lakhs",
  "₹50 - ₹80 Lakhs",
  "₹80 Lakhs - ₹1.5 Crore",
  "Above ₹1.5 Crore"
];

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, projects, onAddProject, onUpdateProject }) => {
  const [showWizard, setShowWizard] = useState(false);
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [generatingLayout, setGeneratingLayout] = useState(false);
  const [aiLayoutOptions, setAiLayoutOptions] = useState<{url: string, style: string}[]>([]);
  const [selectedLayoutIndex, setSelectedLayoutIndex] = useState<number | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  const [details, setDetails] = useState<ConstructionDetails>({
    plotArea: 1000,
    floors: 1,
    floorConfigs: [{ floorNumber: 1, rooms: 2, bathrooms: 1, kitchenType: 'Without Chimney' }],
    parking: false,
    budgetRange: BUDGET_RANGES[1],
    notes: ''
  });

  useEffect(() => {
    if (details.floors !== details.floorConfigs.length) {
      const newConfigs: FloorConfig[] = [];
      for (let i = 1; i <= details.floors; i++) {
        const existing = details.floorConfigs.find(f => f.floorNumber === i);
        if (existing) {
          newConfigs.push(existing);
        } else {
          newConfigs.push({ 
            floorNumber: i, 
            rooms: 2, 
            bathrooms: 1, 
            kitchenType: 'Without Chimney' 
          });
        }
      }
      setDetails(prev => ({ ...prev, floorConfigs: newConfigs }));
    }
  }, [details.floors]);

  const inputClasses = "w-full p-4 rounded-lg border-2 border-slate-200 bg-white text-slate-950 focus:border-construction-yellow outline-none transition-all font-bold";

  const handleNext = async () => {
    if (step === 3) {
      setStep(4);
      handleGenerateLayouts();
    } else {
      setStep(prev => prev + 1);
    }
  };

  const handleBack = () => setStep(prev => prev - 1);

  const handleGenerateLayouts = async () => {
    setGeneratingLayout(true);
    setSelectedLayoutIndex(null);
    const options = await generateTripleLayouts(details);
    setAiLayoutOptions(options);
    setGeneratingLayout(false);
  };

  const updateFloorConfig = (floorNum: number, field: keyof FloorConfig, value: any) => {
    setDetails(prev => ({
      ...prev,
      floorConfigs: prev.floorConfigs.map(f => 
        f.floorNumber === floorNum ? { ...f, [field]: value } : f
      )
    }));
  };

  const handleFinalSubmit = () => {
    if (selectedLayoutIndex === null) return;

    setLoading(true);
    const newProject: Project = {
      id: 'p' + Math.random().toString(36).substr(2, 5),
      customerId: user.id,
      customerName: user.name,
      firstName: user.firstName,
      lastName: user.lastName,
      email: user.email,
      mobile_number: user.phone,
      status: ProjectStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      details,
      estimates: [],
      messages: [],
      selectedLayoutUrl: aiLayoutOptions[selectedLayoutIndex].url
    };

    setTimeout(() => {
      onAddProject(newProject);
      setShowWizard(false);
      setStep(1);
      setLoading(false);
      setAiLayoutOptions([]);
      setSelectedLayoutIndex(null);
    }, 800);
  };

  const handleFinalizeProject = (project: Project) => {
    const updated: Project = {
      ...project,
      status: ProjectStatus.FINALIZED
    };
    onUpdateProject(updated);
  };

  const handleSendMessage = (projectId: string, msgData: Partial<ChatMessage>) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;

    const newMessage: ChatMessage = {
      id: 'm' + Math.random().toString(36).substr(2, 5),
      senderId: user.id,
      senderName: user.name,
      role: user.role,
      ...msgData,
      timestamp: msgData.timestamp || new Date().toISOString(),
    };

    const updated: Project = {
      ...project,
      messages: [...(project.messages || []), newMessage]
    };
    onUpdateProject(updated);
  };

  const activeProjectForChat = projects.find(p => p.id === activeChatId);

  return (
    <div className="max-w-7xl mx-auto p-6 md:p-10">
      <div className="flex flex-col lg:flex-row gap-10">

        <aside className="w-full lg:w-1/4 space-y-6">
          <div className="bg-construction-slate text-white rounded-xl p-8 shadow-xl border-t-8 border-construction-yellow">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-construction-yellow text-construction-slate rounded-xl flex items-center justify-center text-3xl font-black mb-4 transform -rotate-3">
                {user.name.charAt(0)}
              </div>
              <h2 className="text-2xl font-black uppercase tracking-tight italic">{user.name}</h2>
              <p className="text-construction-yellow text-[10px] font-black uppercase tracking-widest mt-1 border-t border-white/20 pt-1">Authorized Site Owner</p>
            </div>
          </div>
          <LocationWidget />
        </aside>

        <div className="flex-grow">
          {activeProjectForChat ? (
            <div className="h-[600px] mb-10">
              <ChatRoom 
                project={activeProjectForChat} 
                currentUser={user} 
                onSendMessage={handleSendMessage}
                onClose={() => setActiveChatId(null)}
              />
            </div>
          ) : (
            <>
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-10 bg-white p-6 rounded-xl border-b-4 border-construction-yellow shadow-sm">
                <div>
                  <h2 className="text-3xl font-black text-construction-slate uppercase italic">Site Registry Dashboard</h2>
                  <p className="text-slate-500 font-bold text-xs uppercase tracking-wider mt-1">Status Tracking & Construction Command</p>
                </div>
                <button 
                  onClick={() => setShowWizard(true)}
                  className="bg-construction-yellow hover:bg-construction-yellowDark text-construction-slate px-8 py-4 rounded-lg font-black uppercase tracking-wider shadow-[4px_4px_0px_0px_rgba(30,41,59,1)] transition-all flex items-center gap-2"
                >
                  <i className="fas fa-drafting-compass"></i>
                  New Site Request
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {projects.length === 0 ? (
                  <div className="col-span-full bg-white border-4 border-dashed border-slate-200 rounded-xl p-20 text-center">
                    <i className="fas fa-hammer text-5xl text-slate-200 mb-6 block"></i>
                    <h3 className="text-2xl font-black text-slate-400 uppercase italic">Registry Empty</h3>
                    <p className="text-slate-400 mt-2 font-bold text-sm uppercase">Submit a blueprint request to start</p>
                  </div>
                ) : (
                  projects.map(p => (
                    <div key={p.id} className="bg-white rounded-xl overflow-hidden shadow-md border-l-8 border-construction-slate flex flex-col group hover:shadow-xl transition-shadow duration-300">
                      {p.selectedLayoutUrl && (
                        <div className="h-40 overflow-hidden relative border-b-2 border-slate-100 bg-slate-50">
                          <img src={p.selectedLayoutUrl} alt="Selected Design" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
                          <div className="absolute top-2 right-2 bg-construction-yellow text-construction-slate text-[8px] font-black px-2 py-1 rounded uppercase">Site Plan Active</div>
                        </div>
                      )}
                      <div className="p-6 flex-grow">
                        <div className="flex justify-between items-start mb-6">
                          <div>
                            <span className={`px-3 py-1 rounded text-[10px] font-black uppercase tracking-tighter ${
                              p.status === ProjectStatus.FINALIZED ? 'bg-green-600 text-white shadow-[2px_2px_0px_0px_rgba(20,83,45,1)]' : 
                              p.status === ProjectStatus.APPROVED ? 'bg-amber-400 text-construction-slate shadow-[2px_2px_0px_0px_rgba(30,41,59,1)]' : 'bg-slate-800 text-white'
                            }`}>
                              {p.status}
                            </span>
                            <p className="text-[10px] text-slate-400 font-black mt-2 uppercase tracking-widest">BATCH ID: {p.id.toUpperCase()}</p>
                          </div>
                          <div className="text-right">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Budget Limit</p>
                            <p className="text-xs font-black text-construction-caution">{p.details.budgetRange}</p>
                          </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4 mb-6">
                          <div className="bg-slate-50 p-3 rounded border-2 border-slate-100 flex items-center gap-3">
                            <i className="fas fa-expand-arrows-alt text-construction-slate/40 text-sm"></i>
                            <div>
                               <p className="text-[9px] text-slate-400 font-black uppercase leading-none">Plot Area</p>
                               <p className="text-sm font-black italic">{p.details.plotArea} SQ FT</p>
                            </div>
                          </div>
                          <div className="bg-slate-50 p-3 rounded border-2 border-slate-100 flex items-center gap-3">
