                className="flex-1 bg-construction-yellow text-construction-slate py-4 rounded font-black uppercase tracking-widest shadow-[4px_4px_0px_0px_rgba(30,41,59,1)] transition-all flex items-center justify-center gap-2 disabled:opacity-30"
              >
                {loading ? <i className="fas fa-spinner fa-spin"></i> : (step === 4 ? (selectedLayoutIndex === null ? 'Select a Design' : 'Confirm & Deploy') : 'Advance Stage')}
              </button>
            </div>
          </div>
        </div>
      )}

      {viewingHistoryProject && (
        <div className="fixed inset-0 z-[220] bg-construction-slate/95 backdrop-blur-xl flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-4xl rounded-3xl overflow-hidden shadow-2xl animate-in zoom-in duration-300 border-4 border-construction-yellow flex flex-col max-h-[85vh]">
             <div className="bg-construction-slate text-white p-6 flex justify-between items-center">
               <h3 className="text-xl font-black uppercase italic tracking-tighter">Design Archive Vault</h3>
               <button onClick={() => setViewingHistoryProject(null)} className="text-white/40 hover:text-white">
                 <i className="fas fa-times-circle text-2xl"></i>
               </button>
             </div>
             <div className="p-8 overflow-y-auto construction-grid flex-grow grid grid-cols-1 md:grid-cols-3 gap-8">
               {viewingHistoryProject.layoutHistory?.map((item, idx) => (
                 <div key={idx} className="bg-white rounded-2xl border-2 border-slate-100 p-4 hover:border-construction-yellow transition-all group flex flex-col">
                    <div className="aspect-square bg-slate-50 rounded-xl overflow-hidden cursor-zoom-in mb-4" onClick={() => setPreviewImageUrl(item.url)}>
                       <img src={item.url} className="w-full h-full object-contain p-2" />
                    </div>
                    <p className="font-black text-construction-slate uppercase italic text-sm">{item.style}</p>
                 </div>
               ))}
             </div>
          </div>
        </div>
      )}

      {previewImageUrl && (
        <ImagePreviewModal 
          url={previewImageUrl} 
          onClose={() => setPreviewImageUrl(null)} 
          title="Architectural Site Layout"
        />
      )}

      {viewingEngineer && (
        <EngineerProfileViewModal 
          engineer={viewingEngineer} 
          onClose={() => setViewingEngineer(null)} 
        />
      )}
    </div>
  );
};

