import React, { useState } from 'react';
import { User, Project, ProjectStatus, Estimate, ChatMessage } from '../types';
import ChatRoom from '../components/ChatRoom';
import ImagePreviewModal from '../components/ImagePreviewModal';

interface EngineerDashboardProps {
  user: User;
  projects: Project[];
  onUpdateProject: (p: Project) => void;
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);
};

const EngineerDashboard: React.FC<EngineerDashboardProps> = ({ user, projects, onUpdateProject }) => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [materialCost, setMaterialCost] = useState<string>('');
  const [laborCost, setLaborCost] = useState<string>('');
  const [tokenPercentage, setTokenPercentage] = useState<number>(5);
  const [message, setMessage] = useState('');
  const [previewImageUrl, setPreviewImageUrl] = useState<string | null>(null);

  const inputClasses = "w-full p-4 rounded-lg border-2 border-slate-200 bg-white text-slate-950 focus:border-construction-yellow outline-none transition-all font-bold";

  const numMaterialCost = Number(materialCost) || 0;
  const numLaborCost = Number(laborCost) || 0;
  const totalCost = numMaterialCost + numLaborCost;
  const tokenAmount = Math.round(totalCost * (tokenPercentage / 100));

  const handleApproveAndQuote = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProject) return;

    const finalEstimate: Estimate = {
      engineerId: user.id,
      engineerName: user.name,
      materialCost: numMaterialCost,
      laborCost: numLaborCost,
      tokenPercentage,
      tokenAmount,
      submittedAt: new Date().toISOString(),
      message
    };

    const updated: Project = {
      ...selectedProject,
      status: ProjectStatus.APPROVED,
      estimates: [finalEstimate],
      messages: selectedProject.messages || []
    };

    onUpdateProject(updated);
    setSelectedProject(null);
  };

  const handleSendMessage = (projectId: string, msgData: Partial<ChatMessage>) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const newMessage: ChatMessage = {
      id: 'm' + Math.random().toString(36).substr(2, 5),
      senderId: user.id,
      senderName: user.name,
      role: user.role,
      ...msgData,
      timestamp: msgData.timestamp || new Date().toISOString(),
    };
    const updated: Project = { ...project, messages: [...(project.messages || []), newMessage] };
    onUpdateProject(updated);
  };

  if (!user.isApproved) {
    return (
      <div className="relative min-h-screen flex items-center justify-center p-6 bg-slate-900">
        <div className="relative z-10 max-w-2xl w-full text-center p-12 bg-white rounded-3xl shadow-2xl border-t-8 border-construction-yellow">
          <i className="fas fa-hard-hat text-4xl text-amber-600 mb-6"></i>
          <h2 className="text-3xl font-black text-construction-slate uppercase italic">Verification Pending</h2>
          <p className="text-slate-500 mt-4 max-w-md mx-auto leading-relaxed">
            Structural engineer credentials for <span className="text-construction-slate font-black underline decoration-construction-yellow">{user.name}</span> are currently undergoing central audit.
          </p>
        </div>
      </div>
    );
  }

  const activeProjectForChat = projects.find(p => p.id === activeChatId);

  return (
    <div className="relative min-h-screen">
      <div className="fixed inset-0 z-0">
        <img src="https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&q=80&w=2070" className="w-full h-full object-cover" />
        <div className="absolute inset-0 bg-slate-900/75 backdrop-blur-[3px]"></div>
      </div>

      <div className="relative z-10 max-w-6xl mx-auto p-6 md:p-10">
        <div className="flex flex-col gap-10">
          {activeProjectForChat ? (
            <div className="h-[600px]">
              <ChatRoom project={activeProjectForChat} currentUser={user} onSendMessage={handleSendMessage} onClose={() => setActiveChatId(null)} />
            </div>
          ) : (
            <>
              <div className="flex justify-between items-center mb-12 bg-white/10 backdrop-blur-xl p-8 rounded-3xl border border-white/20 shadow-2xl">
                <div>
                  <h2 className="text-4xl font-black text-white uppercase italic tracking-tighter">Engineer <span className="text-construction-yellow">Command</span></h2>
                  <p className="text-slate-300 font-bold text-xs uppercase tracking-[0.2em] mt-2">Specialist Active Terminal</p>
                </div>
              </div>

              <div className="space-y-8">
                {projects.map(p => (
                  <div key={p.id} className={`bg-white rounded-3xl shadow-2xl border-l-[12px] transition-all overflow-hidden ${selectedProject?.id === p.id ? 'border-construction-yellow' : 'border-construction-slate'}`}>
                    <div className="p-8">
                      <div className="flex flex-col lg:flex-row justify-between gap-8">
                        <div className="flex-grow">
                          <div className="flex items-center gap-4 mb-4">
                            <span className="font-black text-2xl text-construction-slate uppercase tracking-tight">{p.customerName}'S DEPLOYMENT</span>
                          </div>

                          <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-6">
                            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                              <p className="text-[9px] text-slate-400 font-black uppercase mb-1">Plot Area</p>
                              <p className="font-black text-construction-slate">{p.details.plotArea} SQFT</p>
                            </div>
                            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                              <p className="text-[9px] text-slate-400 font-black uppercase mb-1">Floors</p>
                              <p className="font-black text-construction-slate">{p.details.floors} LEVELS</p>
                            </div>
                            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                              <p className="text-[9px] text-slate-400 font-black uppercase mb-1">Timeline</p>
                              <p className="font-black text-blue-600">{p.details.timelineMonths} MONTHS</p>
                            </div>
                            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                              <p className="text-[9px] text-slate-400 font-black uppercase mb-1">Budget</p>
                              <p className="font-black text-green-600">{p.details.budgetRange}</p>
                            </div>
                            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                              <p className="text-[9px] text-slate-400 font-black uppercase mb-1">Parking</p>
                              <p className="font-black text-construction-slate">{p.details.parking ? 'REQUIRED' : 'NO'}</p>
                            </div>
                          </div>

                          <div className="bg-slate-900 text-white/90 p-6 rounded-2xl border-l-8 border-construction-yellow italic text-sm shadow-xl flex gap-6 items-start">
                            <p className="flex-grow">"{p.details.notes || 'No specific site constraints reported by owner.'}"</p>
                            {p.selectedLayoutUrl && (
                              <div className="w-24 h-24 bg-white/10 rounded-xl overflow-hidden border-2 border-white/20 cursor-zoom-in shrink-0" onClick={() => setPreviewImageUrl(p.selectedLayoutUrl || null)}>
                                <img src={p.selectedLayoutUrl} className="w-full h-full object-cover opacity-80" />
                              </div>
                            )}
                          </div>
                        </div>

                        <div className="flex flex-col gap-3 min-w-[240px]">
                          {p.status === ProjectStatus.SUBMITTED ? (
                            <button onClick={() => setSelectedProject(p)} className="bg-construction-yellow hover:bg-construction-yellowDark text-construction-slate py-5 rounded-xl font-black uppercase tracking-widest shadow-xl">Create Estimate</button>
                          ) : (
                            <div className="text-right bg-green-50 p-5 rounded-2xl border border-green-200">
                              <p className="text-[10px] font-black text-green-700 uppercase mb-2 tracking-widest">Official Quote Dispatched</p>
                              <p className="text-2xl font-black text-construction-slate italic">{formatCurrency((p.estimates[0].materialCost || 0) + (p.estimates[0].laborCost || 0))}</p>
                            </div>
                          )}
                          <button onClick={() => setActiveChatId(p.id)} className="bg-construction-slate text-construction-yellow py-5 rounded-xl font-black uppercase flex items-center justify-center gap-3">
                            <i className="fas fa-comments"></i> Communications
                          </button>
                        </div>
                      </div>

                      {selectedProject?.id === p.id && (
                        <form onSubmit={handleApproveAndQuote} className="mt-12 pt-10 border-t-4 border-slate-100">
                          <h4 className="text-2xl font-black text-construction-slate uppercase italic mb-8">Structural Valuation</h4>
                          <div className="grid grid-cols-2 gap-8 mb-8">
                            <input type="number" required className={inputClasses} placeholder="Materials (₹)" value={materialCost} onChange={e => setMaterialCost(e.target.value)} />
                            <input type="number" required className={inputClasses} placeholder="Labor (₹)" value={laborCost} onChange={e => setLaborCost(e.target.value)} />
                          </div>
                          <textarea className={inputClasses + " h-32"} placeholder="Professional summary..." value={message} onChange={e => setMessage(e.target.value)} />
                          <div className="flex gap-4 mt-8">
                            <button type="submit" className="flex-1 bg-construction-slate text-construction-yellow py-5 rounded-xl font-black uppercase">Submit Quote</button>
                            <button type="button" onClick={() => setSelectedProject(null)} className="px-10 py-5 rounded-xl font-black uppercase text-slate-500 border-2 border-slate-200">Cancel</button>
                          </div>
                        </form>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>

      {previewImageUrl && (
        <ImagePreviewModal url={previewImageUrl} onClose={() => setPreviewImageUrl(null)} title="Project Reference Plan" />
      )}
    </div>
  );
};

