                        <div className="p-8 flex-grow">
                          <div className="flex justify-between items-start mb-8">
                            <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-[0.1em] ${p.status === ProjectStatus.FINALIZED ? 'bg-green-600 text-white shadow-lg' : p.status === ProjectStatus.APPROVED ? 'bg-amber-400 text-construction-slate shadow-lg' : 'bg-slate-800 text-white shadow-lg'}`}>
                                {p.status}
                            </span>
                            <div className="text-right">
                              <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Budget Ceiling</p>
                              <p className="text-sm font-black text-construction-caution">{p.details.budgetRange}</p>
                            </div>
                          </div>
                          <div className="grid grid-cols-2 gap-4 mb-8">
                            <div className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-100 flex items-center gap-4">
                              <div className="w-10 h-10 rounded-xl bg-construction-slate/5 flex items-center justify-center"><i className="fas fa-expand-arrows-alt text-construction-slate/60 text-lg"></i></div>
                              <div><p className="text-[9px] text-slate-400 font-black uppercase leading-none mb-1">Area</p><p className="text-lg font-black italic">{p.details.plotArea} SQFT</p></div>
                            </div>
                            <div className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-100 flex items-center gap-4">
                              <div className="w-10 h-10 rounded-xl bg-construction-slate/5 flex items-center justify-center"><i className="fas fa-calendar-check text-construction-slate/60 text-lg"></i></div>
                              <div><p className="text-[9px] text-slate-400 font-black uppercase leading-none mb-1">Timeline</p><p className="text-lg font-black italic">{p.details.timelineMonths} Months</p></div>
                            </div>
                          </div>
                          {p.status === ProjectStatus.APPROVED && p.estimates.length > 0 && (
                            <div className="bg-amber-50 border-4 border-amber-200 p-6 rounded-2xl mb-6 shadow-inner">
                              <div className="flex items-center justify-between mb-4 border-b-2 border-amber-200 pb-3">
                                <p className="text-xs font-black uppercase text-amber-800 tracking-widest">Engineer's Official Quote</p>
                                <button onClick={() => handleViewEngineer(p.estimates[0].engineerId)} className="text-[10px] font-black uppercase text-amber-700 underline underline-offset-4">Profile</button>
                              </div>
                              <div className="space-y-2 text-sm font-bold text-slate-700">
                                <div className="flex justify-between"><span>Materials:</span> <span>{formatCurrency(p.estimates[0].materialCost)}</span></div>
                                <div className="flex justify-between pb-2"><span>Labor:</span> <span>{formatCurrency(p.estimates[0].laborCost)}</span></div>
                                <div className="flex justify-between pt-4 text-xl text-construction-slate font-black border-t-2 border-amber-200"><span>TOTAL</span> <span className="text-amber-700">{formatCurrency(p.estimates[0].materialCost + p.estimates[0].laborCost)}</span></div>
                              </div>
                            </div>
                          )}
                        </div>
                        <div className="flex flex-col">
                          {p.status === ProjectStatus.APPROVED && (
                            <button onClick={() => handleFinalizeProject(p)} className="w-full bg-green-600 hover:bg-green-700 text-white py-5 font-black uppercase tracking-widest transition-all shadow-[inset_0_-6px_0_0_rgba(20,83,45,1)]">Finalize & Deploy</button>
                          )}
                          {p.status === ProjectStatus.FINALIZED && (
                            <button onClick={() => setActiveChatId(p.id)} className="w-full bg-construction-slate text-construction-yellow py-5 font-black uppercase tracking-widest transition-all hover:bg-black flex items-center justify-center gap-3">
                              <i className="fas fa-hard-hat"></i> Operational Terminal
                            </button>
                          )}
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      {showWizard && (
        <div className="fixed inset-0 z-[160] bg-construction-slate/95 backdrop-blur-md flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl rounded-3xl overflow-hidden shadow-2xl animate-in zoom-in duration-200 border-4 border-construction-yellow flex flex-col max-h-[90vh]">
            <div className="bg-construction-slate text-white p-6 flex justify-between items-center">
              <h3 className="text-xl font-black uppercase tracking-widest italic">Phase {step}: Site Configuration</h3>
              <button onClick={() => {setShowWizard(false); setStep(1); setAiLayoutOptions([]);}} className="text-construction-yellow hover:scale-110"><i className="fas fa-times-circle text-2xl"></i></button>
            </div>
            <div className="p-8 overflow-y-auto construction-grid flex-grow">
              {step === 1 && (
                <div className="space-y-6 max-w-2xl mx-auto">
                  <h4 className="text-2xl font-black text-construction-slate uppercase italic">Structural Scope</h4>
                  <div>
                    <label className="block text-xs font-black text-slate-500 uppercase mb-2">Total Plot Area (SQ FT)</label>
                    <input type="number" className={inputClasses} value={details.plotArea || ''} onChange={e => setDetails({...details, plotArea: Number(e.target.value)})} />
                  </div>
                  <div>
                    <label className="block text-xs font-black text-slate-500 uppercase mb-2">Vertical Floor Count</label>
                    <div className="grid grid-cols-5 gap-3">
                      {[1, 2, 3, 4, 5].map(n => (
                        <button key={n} onClick={() => setDetails({...details, floors: n})} className={`py-4 rounded font-black border-2 transition-all ${details.floors === n ? 'bg-construction-yellow border-construction-slate text-construction-slate' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>{n}</button>
                      ))}
                    </div>
                  </div>
                </div>
              )}
              {step === 2 && (
                <div className="space-y-6 max-w-3xl mx-auto">
                  <h4 className="text-2xl font-black text-construction-slate uppercase italic">Floor Loadout</h4>
                  {details.floorConfigs.map(f => (
                    <div key={f.floorNumber} className="p-5 bg-white border-4 border-slate-100 rounded-lg space-y-4">
                      <p className="font-black text-construction-slate uppercase text-[10px] tracking-widest bg-construction-yellow px-2 py-1 inline-block rounded">LEVEL {f.floorNumber}</p>
                      <div className="grid grid-cols-2 gap-4">
                        <input type="number" className={inputClasses + " p-3 text-sm"} placeholder="Rooms" value={f.rooms || ''} onChange={e => updateFloorConfig(f.floorNumber, 'rooms', Number(e.target.value))} />
                        <input type="number" className={inputClasses + " p-3 text-sm"} placeholder="Baths" value={f.bathrooms || ''} onChange={e => updateFloorConfig(f.floorNumber, 'bathrooms', Number(e.target.value))} />
                      </div>
                    </div>
                  ))}
                </div>
              )}
              {step === 3 && (
                <div className="space-y-6 max-w-2xl mx-auto">
                  <h4 className="text-2xl font-black text-construction-slate uppercase italic">Deployment Schedule</h4>
                  <div className="flex justify-between items-end mb-4">
                     <label className="text-xs font-black text-slate-500 uppercase">Duration (Months)</label>
                     <span className={`text-2xl font-black italic ${isTimeReduced ? 'text-red-600' : 'text-construction-slate'}`}>{details.timelineMonths} MONTHS</span>
                  </div>
                  <input type="range" min="3" max="48" className="w-full h-3 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-construction-slate" value={details.timelineMonths} onChange={e => setDetails({...details, timelineMonths: Number(e.target.value)})} />
                  {isTimeReduced && <div className="p-6 bg-red-50 border-4 border-red-200 rounded-2xl animate-pulse text-red-700 text-[10px] font-black uppercase italic">Urgency Surcharge Alert: Fast-track construction increases costs by 15-25%.</div>}
                </div>
              )}
              {step === 4 && (
                <div className="space-y-8">
                  <div className="text-center">
                    <h4 className="text-3xl font-black text-construction-slate uppercase italic">Select Final Architectural Logic</h4>
                    <p className="text-slate-500 font-bold text-xs uppercase mt-1">Generating {details.floors}-floor blueprints for {details.plotArea} sq ft.</p>
                  </div>
                  {generatingLayout ? (
                    <div className="py-24 text-center"><i className="fas fa-drafting-compass fa-spin text-7xl text-construction-yellow mb-8"></i><p className="text-sm font-black uppercase tracking-[0.3em] text-slate-600 animate-pulse italic">Reticulating Splines for {details.floors} Levels...</p></div>
                  ) : (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                      {aiLayoutOptions.map((opt, idx) => (
                        <div key={idx} onClick={() => setSelectedLayoutIndex(idx)} className={`relative cursor-pointer group rounded-xl overflow-hidden border-4 transition-all ${selectedLayoutIndex === idx ? 'border-construction-yellow shadow-2xl scale-[1.02] z-10' : 'border-slate-100 opacity-60'}`}>
                          <img src={opt.url} className="w-full aspect-square object-contain p-2" />
                          <div className={`p-4 ${selectedLayoutIndex === idx ? 'bg-construction-yellow text-construction-slate' : 'bg-slate-50 text-slate-500'}`}><p className="font-black uppercase italic text-xs">{opt.style}</p></div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
            <div className="p-6 bg-slate-50 flex gap-4 border-t-4 border-construction-yellow">
              {step > 1 && <button onClick={handleBack} className="px-8 py-4 rounded font-black uppercase text-xs text-slate-500 border-2 border-slate-300">Previous</button>}
              <button onClick={step === 4 ? handleFinalSubmit : handleNext} disabled={loading || generatingLayout || (step === 4 && selectedLayoutIndex === null)} className="flex-1 bg-construction-yellow text-construction-slate py-4 rounded font-black uppercase tracking-widest shadow-[4px_4px_0px_0px_rgba(30,41,59,1)] active:translate-y-1 transition-all disabled:opacity-30">
                {loading ? <i className="fas fa-spinner fa-spin"></i> : (step === 4 ? 'Confirm & Deploy' : 'Advance Stage')}
              </button>
            </div>
          </div>
        </div>
      )}

      {showSuccessOverlay && <SuccessTick message="Order Sent to Engineer" subMessage="Review sent for verification" />}

      {viewingHistoryProject && (
        <div className="fixed inset-0 z-[220] bg-construction-slate/95 backdrop-blur-xl flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-4xl rounded-3xl overflow-hidden shadow-2xl border-4 border-construction-yellow flex flex-col max-h-[85vh]">
             <div className="bg-construction-slate text-white p-6 flex justify-between items-center"><h3 className="text-xl font-black uppercase italic tracking-tighter">Design Archive Vault</h3><button onClick={() => setViewingHistoryProject(null)} className="text-white/40 hover:text-white"><i className="fas fa-times-circle text-2xl"></i></button></div>
             <div className="p-8 overflow-y-auto grid grid-cols-1 md:grid-cols-3 gap-8">
               {viewingHistoryProject.layoutHistory?.map((item, idx) => (
                 <div key={idx} className="bg-white rounded-2xl border-2 border-slate-100 p-4 hover:border-construction-yellow transition-all flex flex-col">
                    <div className="aspect-square bg-slate-50 rounded-xl overflow-hidden cursor-zoom-in mb-4" onClick={() => setPreviewImageUrl(item.url)}><img src={item.url} className="w-full h-full object-contain p-2" /></div>
                    <p className="font-black text-construction-slate uppercase italic text-sm">{item.style}</p>
                 </div>
               ))}
             </div>
          </div>
        </div>
      )}

      {previewImageUrl && <ImagePreviewModal url={previewImageUrl} onClose={() => setPreviewImageUrl(null)} title="Architectural Site Layout" />}
      {viewingEngineer && <EngineerProfileViewModal engineer={viewingEngineer} onClose={() => setViewingEngineer(null)} />}
    </div>
  );
};

export default CustomerDashboard;

import React, { useState } from 'react';
import { User, Project, ProjectStatus, Estimate, ChatMessage } from '../types';
import ChatRoom from '../components/ChatRoom';
import ImagePreviewModal from '../components/ImagePreviewModal';
import SuccessTick from '../components/SuccessTick';

interface EngineerDashboardProps {
  user: User;
  projects: Project[];
  onUpdateProject: (p: Project) => void;
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);
};

const EngineerDashboard: React.FC<EngineerDashboardProps> = ({ user, projects, onUpdateProject }) => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [materialCost, setMaterialCost] = useState<string>('');
  const [laborCost, setLaborCost] = useState<string>('');
  const [tokenPercentage, setTokenPercentage] = useState<number>(5);
  const [message, setMessage] = useState('');
  const [previewImageUrl, setPreviewImageUrl] = useState<string | null>(null);
  const [showSuccessOverlay, setShowSuccessOverlay] = useState(false);

  const inputClasses = "w-full p-4 rounded-lg border-2 border-slate-200 bg-white text-slate-950 focus:border-construction-yellow outline-none transition-all font-bold";

  const handleApproveAndQuote = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProject) return;

    const numMaterialCost = Number(materialCost) || 0;
    const numLaborCost = Number(laborCost) || 0;
    const totalCost = numMaterialCost + numLaborCost;
    const tokenAmount = Math.round(totalCost * (tokenPercentage / 100));

    const finalEstimate: Estimate = {
      engineerId: user.id,
      engineerName: user.name,
      materialCost: numMaterialCost,
      laborCost: numLaborCost,
      tokenPercentage,
      tokenAmount,
      submittedAt: new Date().toISOString(),
      message
    };

    const updated: Project = {
      ...selectedProject,
      status: ProjectStatus.APPROVED,
      estimates: [finalEstimate],
      messages: selectedProject.messages || []
    };

    onUpdateProject(updated);
    setSelectedProject(null);
    setMaterialCost('');
    setLaborCost('');

    // SHOW SUCCESS TICK
    setShowSuccessOverlay(true);
    setTimeout(() => setShowSuccessOverlay(false), 3000);
  };

  const handleSendMessage = (projectId: string, msgData: Partial<ChatMessage>) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const newMessage: ChatMessage = {
      id: 'm' + Math.random().toString(36).substr(2, 5),
      senderId: user.id,
      senderName: user.name,
      role: user.role,
      ...msgData,
      timestamp: msgData.timestamp || new Date().toISOString(),
    };
    const updated: Project = { ...project, messages: [...(project.messages || []), newMessage] };
    onUpdateProject(updated);
  };

  if (!user.isApproved) {
    return (
      <div className="relative min-h-screen flex items-center justify-center p-6 bg-slate-900">
        <div className="relative z-10 max-w-2xl w-full text-center p-12 bg-white rounded-3xl shadow-2xl border-t-8 border-construction-yellow">
          <i className="fas fa-hard-hat text-4xl text-amber-600 mb-6"></i>
          <h2 className="text-3xl font-black text-construction-slate uppercase italic">Verification Pending</h2>
          <p className="text-slate-500 mt-4 leading-relaxed font-bold uppercase tracking-widest text-xs">Awaiting Site Credentials Verification</p>
        </div>
      </div>
    );
  }

  const activeProjectForChat = projects.find(p => p.id === activeChatId);

  return (
    <div className="relative min-h-screen">
      <div className="fixed inset-0 z-0">
        <img src="https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&q=80&w=2070" className="w-full h-full object-cover opacity-30" />
        <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-[3px]"></div>
      </div>

      <div className="relative z-10 max-w-6xl mx-auto p-6 md:p-10">
        {activeProjectForChat ? (
          <div className="h-[600px]"><ChatRoom project={activeProjectForChat} currentUser={user} onSendMessage={handleSendMessage} onClose={() => setActiveChatId(null)} /></div>
        ) : (
          <div className="space-y-8">
            <h2 className="text-4xl font-black text-white uppercase italic tracking-tighter mb-12">Engineer <span className="text-construction-yellow">Command Center</span></h2>
            {projects.map(p => (
              <div key={p.id} className={`bg-white rounded-3xl shadow-2xl border-l-[12px] transition-all overflow-hidden ${selectedProject?.id === p.id ? 'border-construction-yellow' : 'border-construction-slate'}`}>
                <div className="p-8">
                  <div className="flex flex-col lg:flex-row justify-between gap-8">
                    <div className="flex-grow">
                      <div className="flex items-center gap-4 mb-4">
                        <span className="font-black text-2xl text-construction-slate uppercase italic">{p.customerName}'S PROJECT</span>
                      </div>
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                        <div className="bg-slate-50 p-4 rounded-xl border border-slate-100"><p className="text-[9px] text-slate-400 font-black uppercase">Area</p><p className="font-black text-xs">{p.details.plotArea} SQFT</p></div>
                        <div className="bg-slate-50 p-4 rounded-xl border border-slate-100"><p className="text-[9px] text-slate-400 font-black uppercase">Floors</p><p className="font-black text-xs">{p.details.floors} LEVELS</p></div>
                        <div className="bg-slate-50 p-4 rounded-xl border border-slate-100"><p className="text-[9px] text-slate-400 font-black uppercase">Timeline</p><p className="font-black text-xs text-blue-600">{p.details.timelineMonths} MONTHS</p></div>
                        <div className="bg-slate-50 p-4 rounded-xl border border-slate-100"><p className="text-[9px] text-slate-400 font-black uppercase">Budget</p><p className="font-black text-xs text-green-600">{p.details.budgetRange}</p></div>
                      </div>
                      <div className="bg-slate-900 text-white/90 p-5 rounded-xl border-l-4 border-construction-yellow text-sm flex gap-6 items-center">
                        <p className="flex-grow italic">"{p.details.notes || 'No notes.'}"</p>
                        {p.selectedLayoutUrl && (
                          <img src={p.selectedLayoutUrl} className="w-16 h-16 rounded cursor-zoom-in border border-white/20" onClick={() => setPreviewImageUrl(p.selectedLayoutUrl || null)} />
                        )}
                      </div>
                    </div>
                    <div className="flex flex-col gap-3 min-w-[200px]">
                      {p.status === ProjectStatus.SUBMITTED ? (
                        <button onClick={() => setSelectedProject(p)} className="bg-construction-yellow text-construction-slate py-4 rounded-xl font-black uppercase text-xs shadow-lg hover:translate-y-[-2px] transition-all">Create Estimate</button>
                      ) : (
                        <div className="p-4 bg-green-50 rounded-xl border border-green-100 text-center"><p className="text-[10px] font-black text-green-700 uppercase">Quote Dispatched</p></div>
                      )}
                      <button onClick={() => setActiveChatId(p.id)} className="bg-construction-slate text-construction-yellow py-4 rounded-xl font-black uppercase text-xs flex items-center justify-center gap-2">
                        <i className="fas fa-comments"></i> Chat
                      </button>
                    </div>
                  </div>
                  {selectedProject?.id === p.id && (
                    <form onSubmit={handleApproveAndQuote} className="mt-8 pt-8 border-t-2 border-slate-100 grid grid-cols-2 gap-4 animate-in slide-in-from-top-4">
                      <input type="number" required className={inputClasses} placeholder="Materials (₹)" value={materialCost} onChange={e => setMaterialCost(e.target.value)} />
                      <input type="number" required className={inputClasses} placeholder="Labor (₹)" value={laborCost} onChange={e => setLaborCost(e.target.value)} />
                      <textarea className={inputClasses + " col-span-2 h-24"} placeholder="Site notes..." value={message} onChange={e => setMessage(e.target.value)} />
                      <button type="submit" className="col-span-2 bg-construction-slate text-construction-yellow py-4 rounded-xl font-black uppercase tracking-widest hover:bg-black">Submit Final Review</button>
                    </form>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {showSuccessOverlay && <SuccessTick message="Review Sent for Review" subMessage="Estimate dispatched to site owner" />}
      {previewImageUrl && <ImagePreviewModal url={previewImageUrl} onClose={() => setPreviewImageUrl(null)} title="Reference Plan" />}
    </div>
  );
};

