  id: string;
  name: string; // Display name
  firstName?: string;
  lastName?: string;
  email: string;
  password?: string;
  role: UserRole;
  isApproved?: boolean;
  experience?: number;
  projectsDone?: number;
  companyName?: string;
  profileImage?: string;
  phone?: string;
  address?: string;
}

