  timestamp: string;
}

export interface Estimate {
  engineerId: string;
  engineerName: string;
  materialCost: number;
  laborCost: number;
  tokenPercentage?: number;
  tokenAmount?: number;
  submittedAt: string;
  message?: string;
}

export interface LayoutArchive {
  url: string;
  style: string;
  generatedAt: string;
  floorCount: number;
}

export interface Project {
  id: string;
  customerId: string;
  customerName: string;
  firstName?: string;
  lastName?: string;
  email?: string;
  mobile_number?: string;
  details: ConstructionDetails;
  status: ProjectStatus;
  createdAt: string;
  estimates: Estimate[];
  messages?: ChatMessage[];
  selectedLayoutUrl?: string;
  layoutHistory?: LayoutArchive[];
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ConstructionDetails, AiEstimateOption } from "../types";

export const getAiEstimateOptions = async (details: ConstructionDetails): Promise<AiEstimateOption[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const floorBreakdown = details.floorConfigs.map(f => 
    `Floor ${f.floorNumber}: ${f.rooms} Rooms, ${f.bathrooms} Bathrooms, Kitchen: ${f.kitchenType}`
  ).join('\n');

  const dimensionString = details.length && details.breadth 
    ? `Plot Dimensions: ${details.length}ft (Length) x ${details.breadth}ft (Breadth)`
    : `Total Area: ${details.plotArea} sq ft`;

  const prompt = `Provide 6 distinct construction cost estimate tiers for a house in India with the following specs:
    - ${dimensionString}
    - Total Floors: ${details.floors}
    - Requested Timeline: ${details.timelineMonths} months
    - Floor Breakdown:
${floorBreakdown}
    - Parking: ${details.parking ? "Required" : "Not Required"}
    - Additional Notes: ${details.notes || "None"}

    The 6 tiers should be:
    1. Economy, 2. Budget-Friendly, 3. Standard, 4. Premium, 5. Luxury, 6. Ultra-Luxury.
    Calculate realistic material and labor costs in INR. Explain briefly what defines each tier.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              label: { type: Type.STRING },
              material: { type: Type.NUMBER },
              labor: { type: Type.NUMBER },
              explanation: { type: Type.STRING },
            },
            required: ["label", "material", "labor", "explanation"],
          }
        },
      },
    });

    return JSON.parse(response.text?.trim() || "[]");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return [];
  }
};

export const generateHouseLayout = async (details: ConstructionDetails, style: string = 'Modernist'): Promise<string | null> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const floorDescriptions = details.floorConfigs.map(f => 
    `Level ${f.floorNumber}: ${f.rooms} rooms, ${f.bathrooms} bathrooms, and a kitchen (${f.kitchenType}).`
  ).join(' ');

  const dimensionContext = details.length && details.breadth 
    ? `The plot is a RECTANGLE of ${details.length}ft by ${details.breadth}ft. The floor plan footprint MUST exactly match this rectangular proportion.`
    : `The plot area is ${details.plotArea} sq ft. Imagine a standard rectangular or square layout.`;

  const prompt = `URGENT ARCHITECTURAL SPEC: Create a 2D technical floor plan for a building with EXACTLY ${details.floors} FLOORS.

    ${dimensionContext}
    Design Style: ${style} architectural technical blueprint.
    Floor Plan Breakdown: ${floorDescriptions}
    ${details.parking ? "Must show Ground Floor parking area." : ""}

    VISUAL REQUIREMENTS: 
    - For ${details.floors} floors, display ALL levels side-by-side or stacked in one sheet.
    - Label each section clearly: "Ground Floor", "1st Floor", etc.
    - Black and white technical line drawing. High precision.
    - Show door swings, window positions, and structural columns.
    - IMPORTANT: Ensure the external boundary reflects the ${details.length}x${details.breadth} proportions if specified.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error(`Gemini Image Generation Error (${style}):`, error);
    return null;
  }
};

export const generateTripleLayouts = async (details: ConstructionDetails): Promise<{url: string, style: string}[]> => {
  const styles = [
    { name: 'Modernist Edge', prompt: 'Modern minimalist luxury with open-plan concepts' },
    { name: 'Classic Heritage', prompt: 'Traditional solid structure with defined separated rooms' },
    { name: 'Eco Minimal', prompt: 'Compact, efficient space optimization with focus on natural flow' }
  ];

  const results = await Promise.all(
    styles.map(async (style) => {
      const url = await generateHouseLayout(details, style.prompt);
      return { url: url || '', style: style.name };
    })
  );

  return results.filter(r => r.url !== r.style && r.url !== '');
};

import React, { useState, useEffect } from 'react';
import { User, Project, ProjectStatus, ConstructionDetails, FloorConfig, Estimate, ChatMessage, LayoutArchive } from '../types';
import ChatRoom from '../components/ChatRoom';
import { generateTripleLayouts } from '../services/geminiService';
import EngineerProfileViewModal from '../components/EngineerProfileViewModal';
import ImagePreviewModal from '../components/ImagePreviewModal';
import SuccessTick from '../components/SuccessTick';

interface CustomerDashboardProps {
  user: User;
  projects: Project[];
  onAddProject: (p: Project) => void;
  onUpdateProject: (p: Project) => void;
  allUsers: User[];
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);
};

const BUDGET_RANGES = [
  "Below ₹15 Lakhs",
  "₹15 - ₹30 Lakhs",
  "₹30 - ₹50 Lakhs",
  "₹50 - ₹80 Lakhs",
  "₹80 Lakhs - ₹1.5 Crore",
  "Above ₹1.5 Crore"
];

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ user, projects, onAddProject, onUpdateProject, allUsers }) => {
  const [showWizard, setShowWizard] = useState(false);
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [generatingLayout, setGeneratingLayout] = useState(false);
  const [aiLayoutOptions, setAiLayoutOptions] = useState<{url: string, style: string}[]>([]);
  const [selectedLayoutIndex, setSelectedLayoutIndex] = useState<number | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [viewingEngineer, setViewingEngineer] = useState<User | null>(null);
  const [previewImageUrl, setPreviewImageUrl] = useState<string | null>(null);
  const [viewingHistoryProject, setViewingHistoryProject] = useState<Project | null>(null);
  const [showSuccessOverlay, setShowSuccessOverlay] = useState(false);
  const [showAdvancedSpecs, setShowAdvancedSpecs] = useState(false);

  const [details, setDetails] = useState<ConstructionDetails>({
    plotArea: 1000,
    floors: 1,
    floorConfigs: [{ floorNumber: 1, rooms: 2, bathrooms: 1, kitchenType: 'Without Chimney' }],
    parking: false,
    budgetRange: BUDGET_RANGES[1],
    timelineMonths: 7,
    notes: '',
    length: 50,
    breadth: 20
  });

  const getDefaultTimeForFloors = (f: number) => {
    if (f === 1) return 7;
    if (f === 2) return 18;
    return 18 + (f - 2) * 8; 
  };

  useEffect(() => {
    setDetails(prev => ({ ...prev, timelineMonths: getDefaultTimeForFloors(prev.floors) }));

    if (details.floors !== details.floorConfigs.length) {
      const newConfigs: FloorConfig[] = [];
      for (let i = 1; i <= details.floors; i++) {
        const existing = details.floorConfigs.find(f => f.floorNumber === i);
        if (existing) {
          newConfigs.push(existing);
        } else {
          newConfigs.push({ 
            floorNumber: i, 
            rooms: 2, 
            bathrooms: 1, 
            kitchenType: 'Without Chimney' 
          });
        }
      }
      setDetails(prev => ({ ...prev, floorConfigs: newConfigs }));
    }
  }, [details.floors]);

  // Sync dimensions with plot area
  useEffect(() => {
    if (showAdvancedSpecs && details.length && details.breadth) {
      const area = details.length * details.breadth;
      if (area !== details.plotArea) {
        setDetails(prev => ({ ...prev, plotArea: area }));
      }
    }
  }, [details.length, details.breadth, showAdvancedSpecs]);

  const inputClasses = "w-full p-4 rounded-lg border-2 border-slate-200 bg-white text-slate-950 focus:border-construction-yellow outline-none transition-all font-bold";

  const handleNext = async () => {
    if (step === 3) {
      setStep(4);
      handleGenerateLayouts();
    } else {
      setStep(prev => prev + 1);
    }
  };

  const handleBack = () => setStep(prev => prev - 1);

  const handleGenerateLayouts = async () => {
    setGeneratingLayout(true);
    setSelectedLayoutIndex(null);
    const options = await generateTripleLayouts(details);
    setAiLayoutOptions(options);
    setGeneratingLayout(false);
  };

  const updateFloorConfig = (floorNum: number, field: keyof FloorConfig, value: any) => {
    setDetails(prev => ({
      ...prev,
      floorConfigs: prev.floorConfigs.map(f => 
        f.floorNumber === floorNum ? { ...f, [field]: value } : f
      )
    }));
  };

  const handleFinalSubmit = () => {
    if (selectedLayoutIndex === null) return;

    setLoading(true);

    const archive: LayoutArchive[] = aiLayoutOptions.map(opt => ({
      url: opt.url,
      style: opt.style,
      generatedAt: new Date().toISOString(),
      floorCount: details.floors
    }));

    const newProject: Project = {
      id: 'p' + Math.random().toString(36).substr(2, 5),
      customerId: user.id,
      customerName: user.name,
      firstName: user.firstName,
      lastName: user.lastName,
      email: user.email,
      mobile_number: user.phone,
      status: ProjectStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      details,
      estimates: [],
      messages: [],
