      layoutHistory: archive
    };

    setTimeout(() => {
      onAddProject(newProject);
      setShowWizard(false);
      setStep(1);
      setLoading(false);
      setAiLayoutOptions([]);
      setSelectedLayoutIndex(null);

      // SHOW SUCCESS TICK
      setShowSuccessOverlay(true);
      setTimeout(() => setShowSuccessOverlay(false), 3500);
